def gen(rng):
    def serialize(vals, left, right):
        out = []
        q = [0]
        h = 0
        while h < len(q):
            u = q[h]
            h += 1
            if u == -1:
                out.append('null')
                continue
            out.append(str(vals[u]))
            q.append(left[u])
            q.append(right[u])
        while out and out[-1] == 'null':
            out.pop()
        return ' '.join(out)

    def make(n, shape):
        left = [-1] * n
        right = [-1] * n
        depth = [1] * n
        if shape == 'random':
            free = [(0, 0), (0, 1)]
            for i in range(1, n):
                k = rng.randrange(len(free))
                free[k], free[-1] = free[-1], free[k]
                p, side = free.pop()
                if side == 0:
                    left[p] = i
                else:
                    right[p] = i
                depth[i] = depth[p] + 1
                free.append((i, 0))
                free.append((i, 1))
        elif shape == 'chain':
            for i in range(1, n):
                if rng.random() < 0.5:
                    left[i - 1] = i
                else:
                    right[i - 1] = i
                depth[i] = depth[i - 1] + 1
        else:
            spine = shape
            free = []
            for i in range(1, n):
                if i < spine:
                    p, side = i - 1, rng.randrange(2)
                    if side == 0:
                        left[p] = i
                    else:
                        right[p] = i
                    depth[i] = depth[p] + 1
                    free.append((p, 1 - side))
                    if i == spine - 1:
                        free.append((i, 0))
                        free.append((i, 1))
                else:
                    k = rng.randrange(len(free))
                    free[k], free[-1] = free[-1], free[k]
                    p, side = free.pop()
                    if side == 0:
                        left[p] = i
                    else:
                        right[p] = i
                    depth[i] = depth[p] + 1
                    free.append((i, 0))
                    free.append((i, 1))
        assert max(depth) <= 5000
        return left, right

    def case(n, shape, lo=1, hi=10**9, pair=None):
        left, right = make(n, shape)
        vals = rng.sample(range(lo, hi + 1), n)
        if pair is None:
            a, b = rng.randrange(n), rng.randrange(n)
        else:
            a, b = pair
        return serialize(vals, left, right) + '\n%d %d' % (vals[a], vals[b])

    tests = []
    tests.append('7\n7 7')
    tests.append('1 2 3\n2 3')
    tests.append('1 2 3 4 5 null 6\n4 6')
    tests.append('5 4 null 3 null 2 null 1\n1 5')
    tests.append('5 null 4 null 3 null 2 null 1\n5 1')
    for n in (2, 3, 4, 6, 8, 10, 14):
        for shape in ('random', 'chain'):
            tests.append(case(n, shape, 1, 40))
    for n in (9, 12, 15, 25):
        tests.append(case(n, 'random', 1, 99))
    tests.append(case(2000, 'random'))
    tests.append(case(5000, 'chain', pair=(0, 4999)))
    tests.append(case(100000, 'random'))
    tests.append(case(100000, 3000))
    tests.append(case(100000, 'random', pair=(0, 99999)))
    return tests

